pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _runTest(address caller, uint64 n, uint64 t, uint256 f, bytes32 h, uint64 s, bytes32 b, uint256 o, uint256 sc) internal {
        vm.assume(caller != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        bool ok;
        try c.setL1BlockValues(n, t, f, h, s, b, o, sc) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }

    function testFuzz_runTest(address caller, uint64 n, uint64 t, uint256 f, bytes32 h, uint64 s, bytes32 b, uint256 o, uint256 sc) public {
        vm.assume(caller.code.length == 0 && uint160(caller) > 0xffff && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _runTest(caller, n, t, f, h, s, b, o, sc);
    }

    receive() external payable {}

    fallback() external payable {}
}
